  AXIOM_BINDS["super-h"] = hl.bind("SUPER + h", hl.dsp.focus({ direction = "left" }), { description = "Window: Focus left" })
  AXIOM_BINDS["super-shift-h"] = hl.bind("SUPER + SHIFT + h", hl.dsp.window.move({ direction = "left" }), { description = "Window: Move left" })
  AXIOM_BINDS["super-l"] = hl.bind("SUPER + l", hl.dsp.focus({ direction = "right" }), { description = "Window: Focus right" })
  AXIOM_BINDS["super-shift-l"] = hl.bind("SUPER + SHIFT + l", hl.dsp.window.move({ direction = "right" }), { description = "Window: Move right" })
