  AXIOM_BINDS["super-shift-0"] = hl.bind("SUPER + SHIFT + 0", hl.dsp.exec_cmd("'/home/user/.local/bin/axiom' ipc workspaces nth '10' move"), { description = "Workspace: Move window to workspace 10" })
