    for _, key in ipairs(AXIOM_SWITCHER_KEYS or {}) do hl.unbind(key) end
    hl.bind("CTRL + SHIFT + Tab", function() hl.dispatch(hl.dsp.event("axiom-switcher:step -1")) end, { repeating = true })
    hl.bind("CTRL + Tab", function() hl.dispatch(hl.dsp.event("axiom-switcher:step 1")) end, { repeating = true })
    hl.bind("Return", function() hl.dispatch(hl.dsp.event("axiom-switcher:commit")); axiom_switcher_leave() end, { ignore_mods = true })
    hl.bind("Escape", function() hl.dispatch(hl.dsp.event("axiom-switcher:cancel")); axiom_switcher_leave() end, { ignore_mods = true })
  end)
  AXIOM_SWITCHER_KEYS = { "CTRL + SHIFT + Tab", "CTRL + Tab", "Return", "Escape" }
  AXIOM_SWITCHER_HELD = { "Control_L", "Control_R" }
  function axiom_switcher_unwatch()
  if AXIOM_SWITCHER_SUB then AXIOM_SWITCHER_SUB:remove() end
  AXIOM_SWITCHER_SUB = nil
end
  function axiom_switcher_leave()
  axiom_switcher_unwatch()
  if hl.get_current_submap() == "axiom_switcher" then hl.dispatch(hl.dsp.submap("reset")) end
end
  function axiom_switcher_watch()
  if AXIOM_SWITCHER_SUB then return end
  AXIOM_SWITCHER_SUB = hl.on("input.keyboard.key", function(_, _, state)
    if state ~= 0 then return end
    AXIOM_SWITCHER_CHECK = hl.timer(function()
      if hl.get_current_submap() ~= "axiom_switcher" then return axiom_switcher_unwatch() end
      for _, key in ipairs(AXIOM_SWITCHER_HELD) do
        if hl.is_key_down(key) then return end
      end
      hl.dispatch(hl.dsp.event("axiom-switcher:commit"))
      axiom_switcher_leave()
    end, { timeout = 10, type = "oneshot" })
  end)
end
end

-- Window borders in the axiom theme, its shape, gaps, Hyprland's blur and
-- window opacity, as enabled. axiom applies them again after every reload,
-- so they win over what follows while they're on.
function M.look()
  hl.config({
    decoration = {
      active_opacity = 1,
      blur = {
        contrast = 0.89,
        enabled = true,
        ignore_opacity = true,
        new_optimizations = true,
        noise = 0.012,
        passes = 2,
        popups = false,
        size = 5,
        special = false,
        vibrancy = 0.17,
        xray = true,
      },
      dim_inactive = true,
      dim_strength = 0.08,
      fullscreen_opacity = 1,
      inactive_opacity = 0.8,
      rounding = 26,
      shadow = { color = "rgba(ffffff02)", enabled = true, offset = { 0, 0 }, range = 29, render_power = 4 },
    },
    general = {
      border_size = 2,
      col = { active_border = "rgb(9ccfd8)", inactive_border = "rgb(403d52)" },
      gaps_in = 3,
      gaps_out = 6,
    },
  })
  hl.window_rule({ name = "axiom-no-window-blur", match = { class = ".*" }, no_blur = true, enabled = false })
end

-- The keyboard, mouse and touchpad, as enabled; applied again after every
-- reload like the look
function M.input()
  hl.config({
    input = {
      accel_profile = "flat",
      kb_layout = "us,de",
      kb_options = "",
      kb_variant = ",neo",
      left_handed = false,
      numlock_by_default = true,
      repeat_delay = 300,
      repeat_rate = 50,
      sensitivity = 0,
      touchpad = { disable_while_typing = true, natural_scroll = false, scroll_factor = 0.99, tap_to_click = true },
    },
  })
  for _, d in ipairs(hl.get_devices and hl.get_devices() or {}) do
    if d.type == "pointer" and d.name and (d.name:find("touchpad", 1, true) or d.name:find("trackpad", 1, true) or d.name:find("clickpad", 1, true)) then
      pcall(hl.device, { name = d.name, accel_profile = "adaptive", left_handed = false, sensitivity = 0.25 })
    end
  end
end

-- Blur behind axiom's surfaces while they're translucent (on or off, so
-- turning it off takes it back), at Hyprland's blur
function M.blur()
  hl.layer_rule({ name = "axiom-blur", match = { namespace = "^axiom-(blur-backing|dock-preview|overlay|powermenu|workspaces|monitor-prompt)$" }, blur = true, blur_popups = true, ignore_alpha = 0.5, xray = false, enabled = true })
  hl.layer_rule({ name = "axiom-blur-popups", match = { namespace = "^axiom-(bar|bar-long|bar-pill|bar-pill-long|bar-floating|bar-floating-long|bar-transparent|bar-transparent-long|popout|popout-under|edge-popout|edge-menu|menu|dock)$" }, blur_popups = true, ignore_alpha = 0.5, xray = false, enabled = true })
  hl.layer_rule({ name = "axiom-blur-backdrops", match = { namespace = "^axiom-(backdrop|polkit|screenshare)$" }, blur = true, ignore_alpha = 0.01, xray = false, enabled = true })
  hl.layer_rule({ name = "axiom-blur-no-anim", match = { namespace = "^axiom-(bar|bar-long|bar-pill|bar-pill-long|bar-floating|bar-floating-long|bar-transparent|bar-transparent-long|border|popout|popout-under|edge-popout|osd|edge-menu|menu|dock|notifications)$" }, no_anim = true, enabled = true })
  hl.layer_rule({ name = "axiom-blur-over-overlay", match = { namespace = "^axiom-(blur-backing-overlay)$" }, blur = true, ignore_alpha = 0.5, xray = false, enabled = true })
end

-- Stacking order of axiom's surfaces (bars, border, edge menus, backdrops)
function M.layers()
  hl.layer_rule({ name = "axiom-border-shadow", match = { namespace = "^axiom-border-shadow$" }, order = 11 })
  hl.layer_rule({ name = "axiom-backdrop", match = { namespace = "^axiom-backdrop$" }, order = 10 })
  hl.layer_rule({ name = "axiom-blur-backing", match = { namespace = "^axiom-blur-backing$" }, order = 9 })
  hl.layer_rule({ name = "axiom-shadows", match = { namespace = "^axiom-shadows$" }, order = 8 })
  hl.layer_rule({ name = "axiom-edge-menu", match = { namespace = "^axiom-edge-menu$" }, order = 7 })
  hl.layer_rule({ name = "axiom-menu", match = { namespace = "^axiom-menu$" }, order = 7 })
  hl.layer_rule({ name = "axiom-popout-under", match = { namespace = "^axiom-popout-under$" }, order = 6 })
  hl.layer_rule({ name = "axiom-bar", match = { namespace = "^axiom-bar$" }, order = 5 })
  hl.layer_rule({ name = "axiom-bar-long", match = { namespace = "^axiom-bar-long$" }, order = 4 })
  hl.layer_rule({ name = "axiom-border", match = { namespace = "^axiom-border$" }, order = 0 })
  hl.layer_rule({ name = "axiom-bar-pill", match = { namespace = "^axiom-bar-pill$" }, order = -1 })
  hl.layer_rule({ name = "axiom-bar-pill-long", match = { namespace = "^axiom-bar-pill-long$" }, order = -2 })
  hl.layer_rule({ name = "axiom-bar-floating", match = { namespace = "^axiom-bar-floating$" }, order = -3 })
  hl.layer_rule({ name = "axiom-bar-floating-long", match = { namespace = "^axiom-bar-floating-long$" }, order = -4 })
  hl.layer_rule({ name = "axiom-bar-transparent", match = { namespace = "^axiom-bar-transparent$" }, order = -5 })
  hl.layer_rule({ name = "axiom-bar-transparent-long", match = { namespace = "^axiom-bar-transparent-long$" }, order = -6 })
  hl.layer_rule({ name = "axiom-dock", match = { namespace = "^axiom-dock$" }, order = -7 })
  hl.layer_rule({ name = "axiom-overlay", match = { namespace = "^axiom-overlay$" }, order = -8 })
  hl.layer_rule({ name = "axiom-blur-backing-overlay", match = { namespace = "^axiom-blur-backing-overlay$" }, no_anim = true, order = -9 })
  hl.layer_rule({ name = "axiom-shadows-overlay", match = { namespace = "^axiom-shadows-overlay$" }, no_anim = true, order = -9 })
  hl.layer_rule({ name = "axiom-osd", match = { namespace = "^axiom-osd$" }, order = -10 })
  hl.layer_rule({ name = "axiom-dock-preview", match = { namespace = "^axiom-dock-preview$" }, order = -10 })
  hl.layer_rule({ name = "axiom-edge-popout", match = { namespace = "^axiom-edge-popout$" }, order = -11 })
  hl.layer_rule({ name = "axiom-popout", match = { namespace = "^axiom-popout$" }, order = -11 })
  hl.layer_rule({ name = "axiom-hot-corner", match = { namespace = "^axiom-hot-corner$" }, order = -12 })
  hl.layer_rule({ name = "axiom-screenshot", match = { namespace = "^axiom-screenshot$" }, no_anim = true, order = -20 })
  hl.layer_rule({ name = "axiom-monitor-prompt", match = { namespace = "^axiom-monitor-prompt$" }, order = -25 })
  hl.layer_rule({ name = "axiom-screenshare", match = { namespace = "^axiom-screenshare$" }, no_anim = true, order = -28 })
  hl.layer_rule({ name = "axiom-polkit", match = { namespace = "^axiom-polkit$" }, order = -30 })
  hl.layer_rule({ name = "axiom-desktop", match = { namespace = "^axiom-desktop$" }, no_anim = true })
end

-- Monitor profiles from the Monitors page: the one for what's connected,
-- again whenever a monitor comes or goes
function M.monitors()
  hl.monitor({ output = "desc:Example Display 0001", mode = "3440x1440@240", position = "0x0", scale = 1, bitdepth = 8, cm = "srgb", disabled = false, mirror = "none", sdrbrightness = 1, sdrsaturation = 1, transform = 0 })
end

-- Strips (the scrolling layout) on the monitors Workspaces lists
function M.strips()

end

-- Your window rules (the Window rules page), the most important last: a
-- later rule wins, so your own after this file win over them
function M.rules()
  hl.window_rule({ name = "axiom-rule-wine-0", match = { xwayland = true }, float = true, no_screen_share = true })
  hl.window_rule({ name = "axiom-rule-wine-1", match = { title = "\\A(?s:.*)(?:Wine)(?s:.*)\\z" }, float = true, no_screen_share = true })
  hl.window_rule({ name = "axiom-rule-steam-0", match = { class = "\\A(?:steam)\\z" }, monitor = "DP-1", workspace = "3", maximize = true })
  hl.window_rule({ name = "axiom-rule-calc-0", match = { class = "\\A(?:(?:org\\.gnome\\.Calculator)|(?:gnome-calculator))\\z" }, workspace = "special:calc silent", float = true, center = true })
  hl.window_rule({ name = "axiom-rule-files-0", match = { class = "\\A(?:org\\.gnome\\.Nautilus)\\z" }, opacity = "0.85 override", no_blur = true })
  hl.window_rule({ name = "axiom-rule-games-0", match = { class = "\\A(?s:.*)(?:\\Asteam_app_[0-9]+\\z)(?s:.*)\\z" }, workspace = "name:games silent", fullscreen = true, immediate = true })
  hl.window_rule({ name = "axiom-rule-games-1", match = { class = "negative:\\A(?:(?:steam))\\z", title = "\\A(?:Game)\\z" }, workspace = "name:games silent", fullscreen = true, immediate = true })
  hl.window_rule({ name = "axiom-rule-pip-0", match = { class = "\\A(?:firefox)\\z", title = "\\A(?s:.*)(?:Picture-in-Picture)(?s:.*)\\z" }, float = true, size = "640 360", pin = true, no_initial_focus = true })
end

function M.setup()
  M.required()
  M.binds()
  M.look()
  M.input()
  M.blur()
  M.layers()
  M.monitors()
  M.strips()
  M.rules()
end

-- Lets axiom see that this file is loaded
AXIOM_INCLUDED = true

return M
